// Golden Portfolio API responses generated by the backend (backend/tests/fixtures/portfolio). Orchestrator-owned:
// never edit a JSON file by hand, copy the regenerated set instead. Tests load them through fixture().
const files = import.meta.glob("./*.json", { eager: true, import: "default" }) as Record<string, unknown>;

export function fixture<T>(name: string): T {
  const key = `./${name}.json`;
  if (!(key in files)) throw new Error(`unknown Portfolio fixture: ${name}`);
  return structuredClone(files[key]) as T;
}

export const FIXTURE_NAMES = Object.keys(files).map(key => key.slice(2, -5)).sort();
